import '/workspace/node_modules/reflect-metadata/Reflect.js';
import {writeFileSync} from 'node:fs';
import {Test} from '/workspace/node_modules/@nestjs/testing/index.js';
import {identityDatabase} from '/workspace/apps/api/tests/support/identity-database.ts';
import {createDatabase} from '/workspace/apps/api/dist/src/infrastructure/database/database.js';
import {AppModule} from '/workspace/apps/api/dist/src/app.module.js';
import {configureTransport} from '/workspace/apps/api/dist/src/http/transport.js';
export default async function setup(){
 const context=await identityDatabase('t068_real_ready');let app;
 try {
  const database=createDatabase(context.environment);
  const module=await Test.createTestingModule({imports:[AppModule.forRoot(context.environment,database)]}).compile();
  app=module.createNestApplication({logger:false,bodyParser:false});
  configureTransport(app,context.environment);await app.listen(3000,'127.0.0.1');
  const status=(await fetch('http://127.0.0.1:3000/health/ready')).status;
  if(status!==200)throw Error('Real readiness unavailable');
  writeFileSync('/reports/integration-ready.json',JSON.stringify({schema:context.environment.databaseSchema,status,realAppModule:true,publishedPorts:0,date:new Date().toISOString()}));
  return async()=>{try{await app.close();}finally{await context.cleanup();}};
 }catch(error){try{await app?.close();}finally{await context.cleanup();}throw error;}
}

