import {spawnSync,spawn} from 'node:child_process';
import {writeFileSync,readdirSync,readFileSync} from 'node:fs';
import {createHash} from 'node:crypto';
import {setTimeout as pause} from 'node:timers/promises';
const action=process.argv[2],run=args=>spawnSync('npm',args,{stdio:'inherit'}).status??1;
writeFileSync(`/reports/${action}-runtime.json`,JSON.stringify({node:process.version,npm:spawnSync('npm',['--version'],{encoding:'utf8'}).stdout.trim(),timezone:process.env.TZ,configs:readdirSync('apps/web').filter(n=>n.startsWith('playwright.')&&n.endsWith('.ts')).map(name=>({path:'apps/web/'+name,sha256:createHash('sha256').update(readFileSync('apps/web/'+name)).digest('hex')}))}));
function need(args){const code=run(args);if(code)process.exit(code);}
need(['run','db:generate']);need(['run','build','--workspace','apps/api']);
const flags=['--maxWorkers=1','--reporter=verbose','--reporter=json',`--outputFile.json=/reports/${action}.json`];
let code=0;
if(action==='checks'){need(['run','lint']);code=run(['run','build']);}
else if(action==='unit-api'||action==='unit-web')code=run(['run','test:unit','--workspace',action==='unit-api'?'apps/api':'apps/web','--',...flags]);
else if(action==='probe'){need(['run','probe:generate']);need(['run','probe:migrate']);code=run(['run','probe:check']);}
else if(action==='crypto-mail')code=run(['run','test:crypto-mail','--workspace','apps/api','--',...flags]);
else if(action==='redaction')code=run(['exec','--workspace','apps/api','--','vitest','run','tests/integration/secret-redaction.spec.ts',...flags]);
else if(action==='integration'){need(['run','probe:generate']);code=run(['run','test:integration','--workspace','apps/api','--','--config','/verification/integration.config.ts',...flags]);}
else if(action==='discovery'){
 need(['exec','--workspace','apps/api','--','vitest','list','src/modules','tests/architecture','--filesOnly']);
 need(['exec','--workspace','apps/api','--','vitest','list','tests/compatibility/runtime.spec.ts','tests/compatibility/postgres.spec.ts','tests/integration','--filesOnly']);
 code=run(['run','test:e2e','--workspace','apps/web','--','--config','playwright.academic-offering.config.ts','--list','--reporter=list,json']);
}
else if(action==='browser')code=run(['run','test:e2e','--workspace','apps/web','--','--config','playwright.academic-offering.config.ts','--reporter=list,json']);
else if(action==='browser-harness')code=run(['run','test:e2e','--workspace','apps/web','--','--config','playwright.academic-offering.config.ts','academic-offering-harness.spec.ts','--reporter=list,json']);
else if(action==='browser-session')code=run(['run','test:e2e','--workspace','apps/web','--','--config','playwright.academic-offering.config.ts','academic-offering-maintenance.spec.ts','--grep','M09 sesión','--reporter=list,json']);
else if(action==='browser-diagnostic')code=run(['run','test:e2e','--workspace','apps/web','--','--config','playwright.academic-offering.config.ts','academic-offering-teaching.spec.ts','--grep','D10 respuesta','--repeat-each=3','--reporter=list,json']);
else if(action==='browser-base') {
 process.env.PLAYWRIGHT_BASE_URL='http://127.0.0.1:4173';
 process.env.PLAYWRIGHT_NO_COPY_PROMPT='1';
 const vite=spawn(process.execPath,['/workspace/node_modules/vite/bin/vite.js','--host','127.0.0.1','--port','4173'],{cwd:'/workspace/apps/web',stdio:'ignore'});
 try {
  let ready=false;
  for(let i=0;i<100;i++){if(vite.exitCode!==null)break;try{ready=(await fetch(process.env.PLAYWRIGHT_BASE_URL)).status===200;}catch{}if(ready)break;await pause(100);}
  if(!ready)throw Error('Base Vite server unavailable');
  code=run(['run','test:e2e','--workspace','apps/web','--','--config','playwright.config.ts','(^|/)harness\\.spec\\.ts$','(^|/)foundations\\.spec\\.ts$','--reporter=list,json']);
 } finally {const exited=new Promise(resolve=>vite.once('exit',resolve));vite.kill('SIGTERM');await exited;}
} else if(action.startsWith('browser-')) {
 const suite=action.slice(8);
 if(!['identity','registration','first-admin','admin-users','password-reset','security','profile','accessibility','login-timing'].includes(suite))throw Error('Rejected config');
 code=run(['run','test:e2e','--workspace','apps/web','--','--config',`playwright.${suite}.config.ts`,'--reporter=list,json']);
} else throw Error('Rejected action');
writeFileSync(`/reports/${action}-command.json`,JSON.stringify({action,exitCode:code,date:new Date().toISOString(),timezone:process.env.TZ})+'\n');process.exitCode=code;
